'use strict';
let placingDraft=null,roomClickSuppressedUntil=0;
const clampRoom=value=>Math.max(0,Math.min(100,value));
const positionStyle=point=>`left:calc(${point.x}% - ${point.x/100} * var(--sticker-size));top:calc(${point.y}% - ${point.y/100} * var(--sticker-size));z-index:${Math.round(point.y*10)+2}`;
function freeRoomHTML(saved){
  const positions={...saved.positions};if(placingItem)positions[placingItem]=placingDraft||saved.positions[placingItem]||{x:50,y:70};
  return `<div class="room-scene free-room ${placingItem?'is-placing':''}" id="shop-room" data-wall="${saved.wall}" data-floor="${saved.floor}"><div class="room-wall"></div><div class="room-floor"></div><div class="room-window" aria-hidden="true"><i></i><i></i></div><div class="room-lamp lamp-left" aria-hidden="true"></div><div class="room-lamp lamp-right" aria-hidden="true"></div><div class="room-name">${text(saved.name)} <span aria-hidden="true">✦</span></div><div class="room-skirt" aria-hidden="true"></div><div class="room-placement-layer" id="shop-placement-layer"><span class="room-item-measure" id="room-item-measure" aria-hidden="true"></span>${Object.entries(positions).map(([id,point])=>{const item=SHOP_ITEM_MAP[id];if(!item)return '';return `<button type="button" class="room-piece ${placingItem===id?'piece-selected':''}" data-roomitem="${id}" style="${positionStyle(point)}" aria-label="${text(item.name)}. Drag to move, or tap for move options." draggable="false">${shopArt(item,125)}</button>`}).join('')}</div><div class="room-door-mat" aria-hidden="true">WELCOME</div></div>`;
}
function placementInstructionHTML(){return `<div class="room-instruction ${placingItem?'placing':''}" role="status">${placingItem?`<span>${shopArt(SHOP_ITEM_MAP[placingItem],42)}</span><span><strong>Place your ${text(SHOP_ITEM_MAP[placingItem].name.toLowerCase())}.</strong><br>Tap anywhere in your shop.</span><button class="small-action" id="cancel-place">Cancel</button>`:'<span aria-hidden="true">☝</span><span>Drag an item to move it.<br>Or tap an item for move options.</span>'}</div>${placingItem?'<div class="placement-controls" aria-label="Move the selected item with buttons"><span>Or use these buttons:</span><button id="move-left" aria-label="Move item left">←</button><button id="move-up" aria-label="Move item up">↑</button><button id="move-down" aria-label="Move item down">↓</button><button id="move-right" aria-label="Move item right">→</button><button class="place-here" id="place-here">Place here ✓</button></div>':''}`}
function beginPlacing(id){const saved=starShop.snapshot();if(!saved.owned.includes(id)||SHOP_ITEM_MAP[id]?.kind!=='item')return;placingItem=id;placingDraft={...(saved.positions[id]||{x:50,y:70})};shopNotice='Tap anywhere in your shop to place your '+SHOP_ITEM_MAP[id].name.toLowerCase()+'.';showShop();$('.shop-room-card')?.scrollIntoView({behavior:'smooth',block:'start'});$('#place-here')?.focus({preventScroll:true});say(shopNotice)}
function placeShopItemAt(id,x,y){if(!starShop.place(id,clampRoom(x),clampRoom(y)))return false;placingItem=null;placingDraft=null;shopNotice='Your '+SHOP_ITEM_MAP[id].name.toLowerCase()+' is in place! You can move it again for free.';showShop();say(shopNotice);document.querySelector(`[data-roomitem="${id}"]`)?.focus({preventScroll:true});return true}
function nudgeShopItem(dx,dy,focusId){if(!placingItem)return;const point=placingDraft||{x:50,y:70};placingDraft={x:clampRoom(point.x+dx),y:clampRoom(point.y+dy)};showShop();if(focusId)$('#'+focusId)?.focus({preventScroll:true})}
function pointInShop(clientX,clientY,offsetX,offsetY){const rect=$('#shop-placement-layer').getBoundingClientRect(),measure=$('#room-item-measure').getBoundingClientRect();const size=measure.width||100;return {x:clampRoom((clientX-rect.left-(offsetX??size/2))/Math.max(1,rect.width-size)*100),y:clampRoom((clientY-rect.top-(offsetY??size/2))/Math.max(1,rect.height-size)*100)}}
function showRoomItemMenu(id){const item=SHOP_ITEM_MAP[id];if(!item)return;openDialog(`<h2>${text(item.name)}</h2><div class="purchase-art">${shopArt(item,120)}</div><p>Move it anywhere, or put it back in My items.<br>You keep the item. This costs no stars.</p><div class="purchase-actions"><button class="primary" id="move-item">Move item ↗</button><button class="secondary" id="put-away">Put away</button></div>`);bind('move-item',()=>{$('#dialog').close();beginPlacing(id)});bind('put-away',()=>{$('#dialog').close();starShop.remove(id);shopNotice='Your '+item.name.toLowerCase()+' is in My items. You can use it again.';showShop();say(shopNotice)})}
function bindRoomPlacement(){
  bind('place-here',()=>{if(placingItem){const point=placingDraft||{x:50,y:70};placeShopItemAt(placingItem,point.x,point.y)}});
  for(const [id,dx,dy] of [['move-left',-5,0],['move-right',5,0],['move-up',0,-5],['move-down',0,5]])bind(id,()=>nudgeShopItem(dx,dy,id));
  $('#shop-room')?.addEventListener('click',event=>{if(Date.now()<roomClickSuppressedUntil)return;if(placingItem){const point=pointInShop(event.clientX,event.clientY);placeShopItemAt(placingItem,point.x,point.y)}});
  document.querySelectorAll('[data-roomitem]').forEach(button=>{
    const id=button.dataset.roomitem;let drag=null;
    button.addEventListener('click',event=>{event.stopPropagation();if(Date.now()<roomClickSuppressedUntil)return;if(placingItem){const point=event.detail===0?(placingDraft||{x:50,y:70}):pointInShop(event.clientX,event.clientY);placeShopItemAt(placingItem,point.x,point.y)}else showRoomItemMenu(id)});
    button.addEventListener('keydown',event=>{if(placingItem||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const point=starShop.snapshot().positions[id];if(!point)return;const delta={ArrowLeft:[-5,0],ArrowRight:[5,0],ArrowUp:[0,-5],ArrowDown:[0,5]}[event.key];placeShopItemAt(id,point.x+delta[0],point.y+delta[1])});
    button.addEventListener('pointerdown',event=>{roomClickSuppressedUntil=0;if(placingItem||(event.button!==undefined&&event.button!==0))return;const rect=button.getBoundingClientRect();drag={pointer:event.pointerId,startX:event.clientX,startY:event.clientY,offsetX:event.clientX-rect.left,offsetY:event.clientY-rect.top,moved:false,point:null};button.setPointerCapture?.(event.pointerId)});
    button.addEventListener('pointermove',event=>{if(!drag||drag.pointer!==event.pointerId)return;if(!drag.moved&&Math.hypot(event.clientX-drag.startX,event.clientY-drag.startY)<6)return;drag.moved=true;drag.point=pointInShop(event.clientX,event.clientY,drag.offsetX,drag.offsetY);button.style.cssText=positionStyle(drag.point);button.classList.add('piece-dragging');event.preventDefault()});
    button.addEventListener('pointerup',event=>{if(!drag||drag.pointer!==event.pointerId)return;const done=drag;drag=null;if(button.hasPointerCapture?.(event.pointerId))button.releasePointerCapture(event.pointerId);if(done.moved&&done.point){roomClickSuppressedUntil=Date.now()+400;placeShopItemAt(id,done.point.x,done.point.y)}});
    button.addEventListener('pointercancel',()=>{if(!drag)return;drag=null;roomClickSuppressedUntil=Date.now()+400;showShop()});
  });
}
